package br.com.onda;
import java.io.*;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.regex.*;
/** Streaming M3U reader. Provider options and executable schemes are never executed. */
final class IptvPlaylist {
 static final class Channel {final String name,group,url,search;Channel(String n,String g,String u){name=n;group=g;url=u;search=SearchText.normalize(n+" "+g);}}
 static String stream(String raw,String base){try{URI u=new URI(raw.trim());if(!u.isAbsolute()&&base!=null&&!base.isEmpty())u=new URI(base).resolve(u);String scheme=u.getScheme();if(!("https".equalsIgnoreCase(scheme)||"http".equalsIgnoreCase(scheme))||u.getHost()==null||u.getUserInfo()!=null||u.getFragment()!=null)return "";String ascii=u.toASCIIString();return scheme.toLowerCase(Locale.ROOT)+ascii.substring(ascii.indexOf(':'));}catch(Exception e){return "";}}
 static String attribute(String line,String key){Matcher m=Pattern.compile("(?:^|\\s)"+Pattern.quote(key)+"=\"([^\"]*)\"",Pattern.CASE_INSENSITIVE).matcher(line);return m.find()?m.group(1).trim():"";}
 static int comma(String value){boolean quote=false;for(int i=0;i<value.length();i++){char c=value.charAt(i);if(c=='\"')quote=!quote;else if(c==','&&!quote)return i;}return -1;}
 static String line(BufferedReader reader)throws IOException{StringBuilder out=new StringBuilder();int c;while((c=reader.read())!=-1){if(c=='\n')break;if(out.length()>=65536)throw new IOException("Linha de lista excessivamente longa.");out.append((char)c);}return c==-1&&out.length()==0?null:out.toString();}
 static List<Channel> read(InputStream input,String base)throws IOException{BufferedReader r=new BufferedReader(new InputStreamReader(input,StandardCharsets.UTF_8));ArrayList<Channel> channels=new ArrayList<>();HashSet<String> seen=new HashSet<>();String line,name="",group="",fallback="";boolean header=false;int number=0;while((line=line(r))!=null){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();if(++number==1)line=line.replace("\uFEFF","");line=line.trim();if(line.length()>65536)throw new IOException("Uma linha da lista excede o tamanho suportado.");if(line.isEmpty())continue;if(line.startsWith("#EXTM3U")){header=true;continue;}if(line.startsWith("#EXT-X-")){String source=stream(base,"");if(source.isEmpty())throw new IOException("Este arquivo é um fluxo HLS. Abra o endereço HTTPS do fluxo como lista.");return Collections.singletonList(new Channel("Transmissão ao vivo","Ao vivo",source));}if(line.startsWith("#EXTINF:")){header=true;int comma=comma(line);name=comma>=0?line.substring(comma+1).trim():"";if(name.isEmpty())name=attribute(line,"tvg-name");group=attribute(line,"group-title");continue;}if(line.startsWith("#EXTGRP:")){fallback=line.substring(8).trim();continue;}if(line.startsWith("#"))continue;String url=stream(line,base);if(!url.isEmpty()&&seen.add(url))channels.add(new Channel(name.isEmpty()?"Canal "+(channels.size()+1):name,group.isEmpty()?fallback:group,url));name="";group="";fallback="";}if(!header||channels.isEmpty())throw new IOException("Nenhum canal HTTP/HTTPS encontrado nesta lista M3U.");return channels;}
}
